        if (lab) { const t = clean([...lab.childNodes].filter((n) => n !== el && !(n.matches && n.matches('input,select,textarea'))).map((n) => n.textContent).join(' ')); if (t) return t; }
        if (el.placeholder) return 'ph:' + el.placeholder;
        if (el.title) return 't:' + el.title;
        let p = el.previousSibling; while (p && !clean(p.textContent)) p = p.previousSibling;
        return p ? '<' + clean(p.textContent).slice(0, 40) : '?';
    };
    const pages = [...document.querySelectorAll('main.page')].filter(shown);
    const out = [];
    for (const page of pages) {
        out.push(`=== PAGE ${page.id}`);
        for (const panel of page.querySelectorAll('section.panel')) {
            const vis = shown(panel);
            const words = (panel.innerText || '').split(/\s+/).filter(Boolean).length;
            const nctl = [...panel.querySelectorAll('button,input:not([type=hidden]),select,textarea')];
            out.push(`--- PANEL #${panel.id} "${panel.getAttribute('aria-label')}" ${vis ? 'shown' : 'HIDDEN'} controls=${nctl.length} (in view ${nctl.filter(shown).length}) words_in_view=${words}`);
            const walk = (node, depth) => {
                for (const el of node.children) {
                    const ind = '  '.repeat(depth);
                    const vis2 = shown(el) ? '' : '~';
                    const tag = el.tagName.toLowerCase();
                    if (tag === 'summary') { out.push(`${ind}${vis2}[fold] ${clean(el.textContent).slice(0, 80)}`); continue; }
                    if (tag === 'details' || tag === 'fieldset') { const lg = el.querySelector(':scope > legend'); out.push(`${ind}${vis2}{${tag}${lg ? ' ' + clean(lg.textContent) : ''}}`); walk(el, depth + 1); continue; }
                    if (tag === 'legend') continue;
                    if (/^h[1-6]$/.test(tag)) { out.push(`${ind}${vis2}# ${clean(el.textContent).slice(0, 80)}`); continue; }
                    if (tag === 'button') { out.push(`${ind}${vis2}[btn] ${clean(el.textContent).slice(0, 40) || el.getAttribute('aria-label') || el.title}`); continue; }
                    if (tag === 'input') { if (el.type === 'hidden') continue; out.push(`${ind}${vis2}[${el.type}] ${labelOf(el).slice(0, 50)}${el.type === 'checkbox' || el.type === 'radio' ? '' : ' =' + String(el.value).slice(0, 15)}`); continue; }
                    if (tag === 'select') { out.push(`${ind}${vis2}[select] ${labelOf(el).slice(0, 40)}: ${[...el.options].map((o) => clean(o.textContent)).slice(0, 8).join(' | ')}`); continue; }
                    if (tag === 'textarea') { out.push(`${ind}${vis2}[textarea] ${labelOf(el).slice(0, 40)}`); continue; }
                    if (tag === 'canvas' || tag === 'img' || tag === 'svg' || tag === 'video') { out.push(`${ind}${vis2}<${tag}>`); continue; }
                    if (tag === 'table') { const rows = el.querySelectorAll('tr').length; const head = clean([...el.querySelectorAll('th')].map((t) => t.textContent).join(' | ')); out.push(`${ind}${vis2}<table rows=${rows}> ${head.slice(0, 120)}`); continue; }
                    if (tag === 'label' && !el.querySelector('input,select,textarea,button')) { const t = clean(el.textContent); if (t) out.push(`${ind}${vis2}"${t.slice(0, 80)}"`); continue; }
                    const hasCtl = el.querySelector('button,input,select,textarea,summary,h1,h2,h3,h4,h5,h6,canvas,table,details,fieldset');
                    if (!hasCtl) { const t = clean(el.innerText || el.textContent); if (t) { const w = t.split(' ').length; out.push(`${ind}${vis2}"${t.slice(0, 90)}"${w > 14 ? ` (${w} words)` : ''}`); } continue; }
                    const cls = (el.className && typeof el.className === 'string') ? el.className.split(' ')[0] : '';
                    if (el.matches('label, .row, .field, [class*=row]')) {
                        // direct text of row as a label
                        const own = clean([...el.childNodes].filter((n) => n.nodeType === 3).map((n) => n.textContent).join(' '));
                        if (own) out.push(`${ind}${vis2}"${own.slice(0, 60)}"`);
                    }
                    walk(el, depth + (cls && /group|row|fold|section|box|card|menu/.test(cls) ? 1 : 0));
                }
            };
            walk(panel, 1);
        }
    }
    return out.join('\n');
})()
